#!/usr/bin/env python3
"""Compile against installed OPAE; never load or execute the result."""
import base64,datetime,gzip,hashlib,json,os,socket,subprocess
from pathlib import Path
assert os.environ.get('TMUX') and socket.gethostname().lower()=='agilex7workstation'
root=Path('/home/uwb_student00/ahls/new_BSP/qualification/ahls-host-offline-01/native-compile-01')
root.mkdir(parents=True,exist_ok=False)
payload={'src/host/ahls_qualification_core.h': '', 'src/host/ahls_qualification_core.c': '', 'src/host/ahls_opae_qualification.c': '', 'tests/ia840f/offline/CMakeLists.txt': '', 'tests/ia840f/offline/test_ahls_qualification.c': ''}
r=dict(time=datetime.datetime.now().astimezone().isoformat(),pane=os.environ['TMUX_PANE'],pid=os.getpid(),sources={},commands=[],scope='source writes + CMake configure/compile/link ONLY; binary NEVER executed')
try:
    for name,encoded in payload.items():
        p=root/'source'/name;p.parent.mkdir(parents=True,exist_ok=True);data=base64.b64decode(encoded);p.write_bytes(data)
        assert p.read_bytes()==data
        r['sources'][name]=hashlib.sha256(data).hexdigest()
    cmds=[['free','-h'],['df','-h',str(root)],['cmake','-S',str(root/'source/tests/ia840f/offline'),'-B',str(root/'build'),'-DCMAKE_BUILD_TYPE=Debug','-DBUILD_OPAE_FRONTEND=ON'],['cmake','--build',str(root/'build'),'--target','ahls_opae_qualification','--parallel','2']]
    for args in cmds:
        p=subprocess.run(args,capture_output=True,text=True,timeout=120)
        r['commands'].append(dict(argv=args,rc=p.returncode,stdout=p.stdout,stderr=p.stderr))
        print('RC',p.returncode,args[0],flush=True)
        if p.returncode:raise RuntimeError('native command failed')
    out=root/'build/ahls_opae_qualification'
    r['artifact']=dict(path=str(out),size=out.stat().st_size,sha256=hashlib.sha256(out.read_bytes()).hexdigest())
    r['compiled']=True
except Exception as e:r['compiled']=False;r['error']=repr(e)
finally:
    raw=json.dumps(r,sort_keys=True).encode();(root/'result.json').write_bytes(raw)
    assert (root/'result.json').read_bytes()==raw
    blob=gzip.compress(raw,mtime=0)
    subprocess.run(['tmux','load-buffer','-b','ia840f_host_native_compile_01','-'],input=blob,check=True)
    print('EVIDENCE ia840f_host_native_compile_01 JSON_SHA256',hashlib.sha256(raw).hexdigest(),'GZIP_SHA256',hashlib.sha256(blob).hexdigest(),'COMPILED',r.get('compiled'),flush=True)
